/**
 * The IAU Catalog of Star Names: every proper name the IAU Working Group on Star Names
 * (WGSN) has approved, 652 of them as of 2026-10-15 -- the names a search finds Sirius,
 * Betelgeuse or Proxima Centauri by.
 *
 * **Vendored, not fetched.** The WGSN publishes the catalogue as a web page
 * (https://exopla.net/star-names/modern-iau-star-names/, kept by the WGSN's secretary,
 * E. Mamajek; the IAU's own page at iau.org/public/themes/naming_stars/ has moved and
 * answered 404 on 2026-10-22). A page is not an interface, and a fourth service whose
 * markup can change under a build is a poor trade for a list that grows by a batch a
 * year. So it is copied here, like the catalog's constants, and refreshed by hand when
 * the WGSN announces a batch. Copied 2026-10-22.
 *
 * The WDS component letter and Washington Double Star identifier -- what says a named
 * star is one member of a multiple system ("Proxima Centauri = alf Cen C") -- are not on
 * that page; they come from the WGSN's machine-readable edition of 2022-04-04
 * (https://www.pas.rochester.edu/~emamajek/WGSN/IAU-CSN.txt), joined by name, so the
 * 201 names adopted since have none.
 *
 * Licence: IAU products are released under CC BY 4.0; credit "IAU Working Group on Star
 * Names (WGSN)". See the README.
 */

/**
 * One name: [name, designation, HIP, Bayer or Flamsteed ID, constellation, WDS
 * component, WDS identifier, RA, Dec (degrees, ICRS at epoch 2000.0), magnitude, band
 * (null for Johnson V), date adopted]. Nulls where the catalogue has nothing. HIP is the
 * join to the stars; the position is the fallback for the names it has no HIP for --
 * mostly exoplanet hosts named through NameExoWorlds.
 */
export type WgsnEntry = readonly [
  name: string,
  designation: string | null,
  hip: number | null,
  bayer: string | null,
  constellation: string | null,
  component: string | null,
  wds: string | null,
  raDeg: number | null,
  decDeg: number | null,
  magnitude: number | null,
  band: string | null,
  adopted: string,
];

